'use strict';
// Self-contained course overview page: <course>/INDICE.html (+ INDICE.md)
// One card per recording with date, teacher, duration, a short topic summary (from
// note/<stem> - sommario.md, generated by the AI after transcription) and quick links.
const fs = require('fs');
const path = require('path');

const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const href = p => p.split('/').map(encodeURIComponent).join('/');

function readSummary(dirs, rec) {
    const f = (rec.notes || []).find(n => / - sommario\.md$/.test(n));
    if (!f) return null;
    try {
        const md = fs.readFileSync(path.join(dirs.notes, f), 'utf8').trim();
        const lines = md.split('\n').map(l => l.trim()).filter(Boolean).filter(l => !/^#/.test(l));
        const bullets = lines.filter(l => /^[-*•]\s+/.test(l)).map(l => l.replace(/^[-*•]\s+/, '').replace(/\*\*/g, ''));
        const text = lines.filter(l => !/^[-*•]\s+/.test(l)).join(' ').replace(/\*\*/g, '');
        return { text, bullets };
    } catch (e) { return null; }
}

function listMaterials(root) {
    const out = [];
    const walk = (d, rel) => {
        let entries = [];
        try { entries = fs.readdirSync(d, { withFileTypes: true }); } catch (e) { return; }
        for (const e of entries.sort((a, b) => a.name.localeCompare(b.name, 'it', { numeric: true }))) {
            if (e.name.startsWith('.') || e.name.endsWith('.part')) continue;
            const r = rel ? rel + '/' + e.name : e.name;
            if (e.isDirectory()) walk(path.join(d, e.name), r);
            else out.push(r);
        }
    };
    walk(root, '');
    return out;
}

function render({ course, recs, dirs, DIRS }) {
    const title = course ? course.fullname : 'Registrazioni';
    const sorted = recs.slice().sort((a, b) => (b.isoDate || '').localeCompare(a.isoDate || ''));
    const mats = listMaterials(path.join(dirs.root, 'materiale')).filter(f => f !== 'LINK.md');
    const bySection = {};
    for (const m of mats) { const s = m.includes('/') ? m.split('/')[0] : 'Generale'; (bySection[s] = bySection[s] || []).push(m); }
    const hasLinks = fs.existsSync(path.join(dirs.root, 'materiale', 'LINK.md'));

    const cards = sorted.map(r => {
        const sum = readSummary(dirs, r);
        const links = [];
        if (r.videoExists) links.push(`<a class="btn primary" href="${href(DIRS.video + '/' + r.file)}">▶ Video</a>`);
        if (r.webexUrl) links.push(`<a class="btn" href="${esc(r.webexUrl)}" target="_blank">WebEx</a>`);
        if (r.transcript) links.push(`<a class="btn" href="${href(DIRS.transcripts + '/' + r.transcript)}">Trascrizione</a>`);
        for (const n of r.notes || []) {
            if (/ - sommario\.md$/.test(n)) continue;
            links.push(`<a class="btn" href="${href(DIRS.notes + '/' + n)}">${esc(n.split(' - ').pop().replace(/\.md$/, ''))}</a>`);
        }
        const d = r.isoDate ? new Date(r.isoDate) : null;
        const day = d ? d.toLocaleDateString('it-IT', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' }) : '';
        const search = [r.displayTitle, r.teacher, r.type, sum && sum.text, sum && sum.bullets.join(' ')].join(' ').toLowerCase();
        return `<article class="card" data-search="${esc(search)}" id="${esc(r.key)}">
  <div class="meta"><span>${esc(day)}</span>${r.teacher ? `<span>· ${esc(r.teacher)}</span>` : ''}${r.type ? `<span class="tag">${esc(r.type)}</span>` : ''}${r.duration ? `<span>· ${esc(r.duration)}</span>` : ''}</div>
  <h2>${esc(r.displayTitle || r.topic || r.file)}</h2>
  ${sum ? `${sum.text ? `<p class="sum">${esc(sum.text)}</p>` : ''}${sum.bullets.length ? `<ul>${sum.bullets.map(b => `<li>${esc(b)}</li>`).join('')}</ul>` : ''}`
                : `<p class="sum muted">${r.transcript ? 'Sommario non ancora generato.' : r.videoExists ? 'In attesa di trascrizione.' : 'Video non scaricato.'}</p>`}
  <div class="links">${links.join('') || '<span class="muted">—</span>'}</div>
</article>`;
    }).join('\n');

    const toc = sorted.map(r => `<a href="#${esc(r.key)}"><span>${esc((r.isoDate || '').slice(5, 10).split('-').reverse().join('/'))}</span>${esc(r.displayTitle || '')}</a>`).join('');

    const matHtml = Object.keys(bySection).length || hasLinks ? `<section class="materials"><h2 class="sec">Materiale del corso</h2>
${Object.entries(bySection).map(([s, files]) => `<details><summary>${esc(s)} <span class="muted">(${files.length})</span></summary><ul>${files.map(f => `<li><a href="${href('materiale/' + f)}">${esc(f.split('/').slice(1).join('/') || f)}</a></li>`).join('')}</ul></details>`).join('\n')}
${hasLinks ? `<p><a class="btn" href="materiale/LINK.md">Link esterni</a></p>` : ''}</section>` : '';

    return `<!doctype html>
<html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(title)}</title>
<style>
:root{--bg:#f5f5f7;--card:#fff;--text:#1d1d1f;--muted:#6e6e73;--line:#e5e5ea;--accent:#0071e3;--tag:#f0f0f3}
@media (prefers-color-scheme:dark){:root{--bg:#000;--card:#1c1c1e;--text:#f5f5f7;--muted:#98989d;--line:#2c2c2e;--accent:#2997ff;--tag:#2c2c2e}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 -apple-system,BlinkMacSystemFont,"SF Pro Text","Segoe UI",Roboto,sans-serif}
.wrap{max-width:1100px;margin:0 auto;padding:40px 16px 80px;display:grid;grid-template-columns:240px 1fr;gap:32px}
header{grid-column:1/-1}h1{font-size:30px;letter-spacing:-.02em;margin:0 0 6px}.sub{color:var(--muted)}
input{width:100%;margin-top:18px;padding:11px 14px;border-radius:12px;border:1px solid var(--line);background:var(--card);color:var(--text);font:inherit}
nav{position:sticky;top:20px;align-self:start;max-height:calc(100vh - 40px);overflow:auto;font-size:13px}
nav a{display:block;padding:6px 8px;border-radius:8px;color:var(--text);text-decoration:none;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
nav a:hover{background:var(--card)}nav a span{color:var(--muted);margin-right:8px;font-variant-numeric:tabular-nums}
.card{background:var(--card);border-radius:16px;padding:20px 22px;margin-bottom:14px;box-shadow:0 1px 2px rgba(0,0,0,.04)}
.card h2{font-size:18px;margin:4px 0 8px;letter-spacing:-.01em}.meta{display:flex;gap:6px;flex-wrap:wrap;color:var(--muted);font-size:13px;align-items:center}
.tag{background:var(--tag);border-radius:6px;padding:1px 7px;font-size:12px}.sum{margin:6px 0}ul{margin:6px 0 4px;padding-left:20px}li{margin:2px 0}
.muted{color:var(--muted)}.links{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
.btn{display:inline-block;padding:6px 12px;border-radius:980px;background:var(--tag);color:var(--text);text-decoration:none;font-size:13px}
.btn.primary{background:var(--accent);color:#fff}.btn:hover{filter:brightness(.95)}
.sec{font-size:20px;margin:36px 0 12px}details{background:var(--card);border-radius:12px;padding:12px 16px;margin-bottom:8px}
summary{cursor:pointer;font-weight:600}details a{color:var(--accent);text-decoration:none}
@media (max-width:760px){.wrap{grid-template-columns:1fr}nav{display:none}}
</style></head><body><div class="wrap">
<header><h1>${esc(title)}</h1><div class="sub">${recs.length} registrazioni · ${recs.filter(r => r.videoExists).length} scaricate · ${recs.filter(r => r.transcript).length} trascritte · aggiornato ${new Date().toLocaleString('it-IT')}</div>
<input id="q" placeholder="Cerca per argomento, docente, parola chiave…" autocomplete="off"></header>
<nav>${toc}</nav>
<main>${cards || '<p class="muted">Nessuna registrazione.</p>'}${matHtml}</main>
</div>
<script>
document.getElementById('q').addEventListener('input',e=>{const q=e.target.value.toLowerCase().trim();document.querySelectorAll('.card').forEach(c=>{c.style.display=!q||c.dataset.search.includes(q)?'':'none'})});
</script></body></html>`;
}

module.exports = { render, readSummary };
